package com.watermelon.subtitle.hash

import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import java.nio.file.Files

class OpenSubtitlesHasherTest {

    @Test
    fun hashesMinimumTwoChunksOfZeroBytes() {
        val file = Files.createTempFile("opensubtitles-128k-", ".bin").toFile()
        try {
            file.writeBytes(ByteArray(131_072))
            assertEquals("0000000000020000", OpenSubtitlesHasher.hash(file))
        } finally {
            file.delete()
        }
    }

    @Test
    fun hashesLargerZeroFilledFileIncludingItsSize() {
        val file = Files.createTempFile("opensubtitles-large-", ".bin").toFile()
        try {
            file.writeBytes(ByteArray(262_144))
            assertEquals("0000000000040000", OpenSubtitlesHasher.hash(file))
        } finally {
            file.delete()
        }
    }

    @Test
    fun preservesUnsignedHighBitThroughWrappingLongArithmetic() {
        val bytes = ByteArray(131_072)
        // First little-endian uint64 word of the head chunk is 0x8000000000000000.
        bytes[7] = 0x80.toByte()
        val file = Files.createTempFile("opensubtitles-high-bit-", ".bin").toFile()
        try {
            file.writeBytes(bytes)
            assertEquals("8000000000020000", OpenSubtitlesHasher.hash(file))
        } finally {
            file.delete()
        }
    }

    @Test
    fun sumsHeadAndTailWithoutOverlapAtMinimumSize() {
        val bytes = ByteArray(131_072)
        bytes[0] = 1                 // head word = 1
        bytes[65_536] = 2            // tail word = 2
        val file = Files.createTempFile("opensubtitles-head-tail-", ".bin").toFile()
        try {
            file.writeBytes(bytes)
            // 1 + 2 + fileSize(0x20000) = 0x20003
            assertEquals("0000000000020003", OpenSubtitlesHasher.hash(file))
        } finally {
            file.delete()
        }
    }

    @Test
    fun rejectsFilesSmallerThanTwoChunks() {
        listOf(65_535, 65_536, 131_071).forEach { size ->
            val file = Files.createTempFile("opensubtitles-short-", ".bin").toFile()
            try {
                file.writeBytes(ByteArray(size))
                assertThrows(IllegalArgumentException::class.java) {
                    OpenSubtitlesHasher.hash(file)
                }
            } finally {
                file.delete()
            }
        }
    }
}

package com.watermelon.subtitle.sync

import com.watermelon.common.model.ParsedSubtitle
import com.watermelon.common.model.SubtitleCue
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class SubtitleProbeSelectorImplTest {

    private val selector = SubtitleProbeSelectorImpl()

    @Test
    fun returnsEmptyForEmptySubtitleNonPositiveDurationOrNonPositiveMaxCount() {
        val subtitle = subtitle(0L, 60_000L)
        assertTrue(selector.select(ParsedSubtitle(emptyList()), 60_000L, 3).isEmpty())
        assertTrue(selector.select(subtitle, 0L, 3).isEmpty())
        assertTrue(selector.select(subtitle, -1L, 3).isEmpty())
        assertTrue(selector.select(subtitle, 60_000L, 0).isEmpty())
        assertTrue(selector.select(subtitle, 60_000L, -1).isEmpty())
    }

    @Test
    fun clampsProbeDurationToShortMediaDuration() {
        // Four 500 ms cues within 3,000 ms: occupancy 2,000/3,000 = 0.67, in the accepted band.
        val subtitle = subtitle(0L, 3_000L, count = 4, cueLengthMs = 500L, strideMs = 700L)
        val selected = selector.select(subtitle, 3_000L, 3)
        assertTrue(selected.isNotEmpty())
        assertTrue(selected.all { it.durationMs == 3_000L })
        assertTrue(selected.all { it.subtitleStartMs in 0L..0L })
    }

    @Test
    fun neverReturnsMoreCandidatesThanMaxCount() {
        val subtitle = subtitle(0L, 600_000L, count = 40, cueLengthMs = 1_200L, strideMs = 15_000L)
        assertTrue(selector.select(subtitle, 600_000L, 2).size <= 2)
        assertTrue(selector.select(subtitle, 600_000L, 8).size <= 8)
    }

    @Test
    fun skipsWindowsWithTooFewTransitions() {
        val single = ParsedSubtitle(listOf(SubtitleCue(0, 1_000L, 3_000L, "alone")))
        assertTrue(selector.select(single, 60_000L, 3).isEmpty())
    }

    private fun subtitle(
        startMs: Long,
        endMs: Long,
        count: Int,
        cueLengthMs: Long = 1_000L,
        strideMs: Long = 5_000L,
    ): ParsedSubtitle {
        var cursor = startMs
        val cues = (0 until count).map { index ->
            val cue = SubtitleCue(index, cursor, cursor + cueLengthMs, "Dialogue $index")
            cursor += strideMs
            cue
        }
        // Keep the helper's endMs parameter meaningful for single-cue callers.
        if (count == 1) return ParsedSubtitle(listOf(SubtitleCue(0, startMs, endMs, "alone")))
        return ParsedSubtitle(cues)
    }
}

