use serde::{Deserialize, Serialize};

/// Golden-vector float encoding: the Kotlin oracle stores both a shortest decimal and raw bits.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Float32 {
    pub decimal: String,
    pub bits: String,
}

impl Float32 {
    pub fn value(&self) -> f32 {
        if let Ok(value) = self.decimal.parse::<f32>() {
            return value;
        }
        let bits = u32::from_str_radix(&self.bits, 16).unwrap_or(0);
        f32::from_bits(bits)
    }
}

/// Golden-vector f64 encoding used by affine sync models.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Float64 {
    pub decimal: String,
    pub bits: String,
}

impl Float64 {
    pub fn value(&self) -> f64 {
        if let Ok(value) = self.decimal.parse::<f64>() {
            return value;
        }
        let bits = u64::from_str_radix(&self.bits, 16).unwrap_or(0);
        f64::from_bits(bits)
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ActivitySignature {
    pub start_ms: i64,
    pub bucket_ms: i32,
    pub occupancy: Vec<f32>,
    pub onsets: Vec<f32>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SubtitleCue {
    pub index: i32,
    pub start_ms: i64,
    pub end_ms: i64,
    pub raw_text: String,
    pub base_rtl: bool,
    pub display_text: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ParsedSubtitle {
    #[serde(default)]
    pub cues: Vec<SubtitleCue>,
    #[serde(default)]
    pub language: Option<String>,
    #[serde(default = "default_source_id")]
    pub source_id: String,
    #[serde(default)]
    pub offset_ms: i64,
}

fn default_source_id() -> String {
    "local".to_owned()
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SyncAnchor {
    pub subtitle_time_ms: i64,
    pub media_time_ms: i64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind")]
pub enum SyncModel {
    Identity,
    Offset {
        #[serde(rename = "offsetMs")]
        offset_ms: i64,
    },
    Affine {
        scale: Float64,
        #[serde(rename = "offsetMs")]
        offset_ms: i64,
    },
    Piecewise {
        anchors: Vec<SyncAnchor>,
    },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SyncMeasurement {
    pub subtitle_probe_start_ms: i64,
    pub audio_probe_start_ms: i64,
    pub estimated_offset_ms: i64,
    pub correlation_score: Float32,
    pub peak_margin: Float32,
    pub speech_coverage: Float32,
    pub transition_count: i32,
    pub probe_quality: Float32,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CorrelationConfig {
    pub min_offset_ms: i64,
    pub max_offset_ms: i64,
    pub step_ms: i64,
    pub onset_weight: Float32,
    pub occupancy_weight: Float32,
    pub silence_weight: Float32,
    pub independent_peak_distance_ms: i64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ProbeCandidate {
    pub subtitle_start_ms: i64,
    pub duration_ms: i64,
    pub distinctiveness: f32,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DriftCue {
    pub start_ms: i64,
    pub end_ms: i64,
    pub text: String,
}

/// Kotlin's Double.roundToLong() is floor(x + 0.5), not Rust's half-away-from-zero round().
pub fn kotlin_round_to_long(value: f64) -> i64 {
    (value + 0.5).floor() as i64
}

const FSI: char = '\u{2068}';
const PDI: char = '\u{2069}';

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Dir {
    Rtl,
    Ltr,
    Neutral,
}

fn direction_of(ch: char) -> Dir {
    let code = ch as u32;
    let rtl = (0x0590..=0x05FF).contains(&code)
        || (0x0600..=0x06FF).contains(&code)
        || (0x0750..=0x077F).contains(&code)
        || (0x08A0..=0x08FF).contains(&code)
        || (0xFB50..=0xFDFF).contains(&code)
        || (0xFE70..=0xFEFF).contains(&code);
    if rtl {
        return Dir::Rtl;
    }
    let ltr = ch.is_ascii_uppercase()
        || ch.is_ascii_lowercase()
        || ch.is_ascii_digit()
        || (0x00C0..=0x024F).contains(&code);
    if ltr {
        return Dir::Ltr;
    }
    Dir::Neutral
}

/// True when RTL-script characters dominate the strongly directional characters.
pub fn is_rtl(text: &str) -> bool {
    let mut rtl = 0usize;
    let mut ltr = 0usize;
    for ch in text.chars() {
        match direction_of(ch) {
            Dir::Rtl => rtl += 1,
            Dir::Ltr => ltr += 1,
            Dir::Neutral => {}
        }
    }
    rtl > ltr
}

/// Isolate maximal opposite-base runs in FSI..PDI, keeping trailing neutrals outside.
pub fn format(text: &str, base_rtl: bool) -> String {
    if text.is_empty() {
        return String::new();
    }
    let isolate_dir = if base_rtl { Dir::Ltr } else { Dir::Rtl };
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::with_capacity(text.len() + 8);
    let mut i = 0usize;
    while i < chars.len() {
        if direction_of(chars[i]) == isolate_dir {
            let mut run = String::new();
            let mut trailing_neutrals = String::new();
            while i < chars.len() {
                match direction_of(chars[i]) {
                    dir if dir == isolate_dir => {
                        run.push_str(&trailing_neutrals);
                        trailing_neutrals.clear();
                        run.push(chars[i]);
                        i += 1;
                    }
                    Dir::Neutral => {
                        trailing_neutrals.push(chars[i]);
                        i += 1;
                    }
                    _ => break,
                }
            }
            out.push(FSI);
            out.push_str(&run);
            out.push(PDI);
            out.push_str(&trailing_neutrals);
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

use std::sync::LazyLock;

use regex::Regex;

use crate::bidi;
use crate::contracts::{ParsedSubtitle, SubtitleCue};

static TIME: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(\d{1,2}):(\d{2}):(\d{2})[,.](\d{1,3})").unwrap());
static TAG: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"</?[a-zA-Z][^>]*>").unwrap());
static BLOCK_SPLIT: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"\n[ \t]*\n").unwrap());

fn capture_to_ms(caps: &regex::Captures<'_>, offset: usize) -> i64 {
    let hours: i64 = caps[offset].parse().unwrap_or(0);
    let minutes: i64 = caps[offset + 1].parse().unwrap_or(0);
    let seconds: i64 = caps[offset + 2].parse().unwrap_or(0);
    let raw_ms = &caps[offset + 3];
    let padded = format!("{:<0width$}", raw_ms, width = 3);
    let millis: i64 = padded[..3.min(padded.len())].parse().unwrap_or(0);
    hours * 3_600_000 + minutes * 60_000 + seconds * 1_000 + millis
}

/// Port of SrtParser.parse: BOM/CRLF tolerant, tag stripping, bidi resolution at parse time.
pub fn parse(content: &str, language: Option<&str>) -> ParsedSubtitle {
    let without_bom = content.strip_prefix('\u{feff}').unwrap_or(content);
    let text = without_bom.replace("\r\n", "\n").replace('\r', "\n");
    let mut cues = Vec::new();
    for block in BLOCK_SPLIT.split(&text) {
        let lines: Vec<&str> = block
            .split('\n')
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .collect();
        let Some(timing_idx) = lines.iter().position(|line| line.contains("-->")) else {
            continue;
        };
        let times: Vec<regex::Captures<'_>> = TIME.captures_iter(lines[timing_idx]).collect();
        if times.len() < 2 {
            continue;
        }
        let start = capture_to_ms(&times[0], 1);
        let end = capture_to_ms(&times[1], 1);
        let body = lines[timing_idx + 1..].join("\n");
        if body.trim().is_empty() {
            continue;
        }
        let clean = TAG.replace_all(&body, "").trim().to_owned();
        let rtl = bidi::is_rtl(&clean);
        let display = clean
            .split('\n')
            .map(|line| bidi::format(line, rtl))
            .collect::<Vec<_>>()
            .join("\n");
        cues.push(SubtitleCue {
            index: cues.len() as i32,
            start_ms: start,
            end_ms: end,
            raw_text: clean,
            base_rtl: rtl,
            display_text: display,
        });
    }
    cues.sort_by_key(|cue| cue.start_ms);
    ParsedSubtitle {
        cues,
        language: language.map(str::to_owned),
        source_id: "local".to_owned(),
        offset_ms: 0,
    }
}

