const CHUNK_SIZE: usize = 64 * 1024;
const MIN_FILE_SIZE: usize = CHUNK_SIZE * 2;

/// The golden corpus stores deterministic synthetic patterns rather than copyrighted media.
pub fn hash_synthetic(size: usize, pattern: &str) -> Result<String, String> {
    if size < MIN_FILE_SIZE {
        return Err(format!(
            "File must be at least {MIN_FILE_SIZE} bytes for OpenSubtitles hashing"
        ));
    }
    let mut bytes = vec![0u8; size];
    match pattern {
        "zeros_128k" | "zeros_256k" => {}
        "head_and_tail_words" => {
            bytes[0] = 1;
            bytes[CHUNK_SIZE] = 2;
        }
        "high_bit_head" => bytes[7] = 0x80,
        other => return Err(format!("unknown golden hash pattern: {other}")),
    }
    Ok(hash_bytes(&bytes))
}

pub fn hash_bytes(bytes: &[u8]) -> String {
    let file_size = bytes.len() as u64;
    let head = sum_chunk(bytes, 0);
    let tail = sum_chunk(bytes, bytes.len() - CHUNK_SIZE);
    let hash = file_size
        .wrapping_add(head)
        .wrapping_add(tail);
    format!("{hash:016x}")
}

fn sum_chunk(bytes: &[u8], offset: usize) -> u64 {
    let mut sum = 0u64;
    for i in 0..(CHUNK_SIZE / 8) {
        let start = offset + i * 8;
        let word = u64::from_le_bytes(bytes[start..start + 8].try_into().unwrap());
        sum = sum.wrapping_add(word);
    }
    sum
}

use crate::contracts::{kotlin_round_to_long, SyncModel};

pub fn map(model: &SyncModel, timestamp_ms: i64) -> i64 {
    let mapped = match model {
        SyncModel::Identity => timestamp_ms,
        SyncModel::Offset { offset_ms } => timestamp_ms + offset_ms,
        SyncModel::Affine { scale, offset_ms } => {
            kotlin_round_to_long(timestamp_ms as f64 * scale.value()) + offset_ms
        }
        SyncModel::Piecewise { anchors } => map_piecewise(timestamp_ms, anchors),
    };
    mapped.max(0)
}

fn map_piecewise(time_ms: i64, anchors: &[crate::contracts::SyncAnchor]) -> i64 {
    let mut anchors = anchors.to_vec();
    anchors.sort_by_key(|anchor| anchor.subtitle_time_ms);
    if anchors.is_empty() {
        return time_ms;
    }
    if anchors.len() == 1 {
        return time_ms + (anchors[0].media_time_ms - anchors[0].subtitle_time_ms);
    }
    if time_ms <= anchors[0].subtitle_time_ms {
        let a = &anchors[0];
        return time_ms + (a.media_time_ms - a.subtitle_time_ms);
    }
    if time_ms >= anchors[anchors.len() - 1].subtitle_time_ms {
        let a = &anchors[anchors.len() - 1];
        return time_ms + (a.media_time_ms - a.subtitle_time_ms);
    }
    let right_index = anchors
        .iter()
        .position(|anchor| anchor.subtitle_time_ms >= time_ms)
        .unwrap();
    let left = &anchors[right_index - 1];
    let right = &anchors[right_index];
    let span = (right.subtitle_time_ms - left.subtitle_time_ms).max(1);
    let t = (time_ms - left.subtitle_time_ms) as f64 / span as f64;
    kotlin_round_to_long(left.media_time_ms as f64 + t * (right.media_time_ms - left.media_time_ms) as f64)
}

use crate::contracts::DriftCue;

pub fn apply(cues: &[DriftCue], offset_ms: i64) -> Vec<DriftCue> {
    cues.iter()
        .map(|cue| DriftCue {
            start_ms: (cue.start_ms + offset_ms).max(0),
            end_ms: (cue.end_ms + offset_ms).max(0),
            text: cue.text.clone(),
        })
        .collect()
}

pub fn apply_to_timestamp(timestamp_ms: i64, offset_ms: i64) -> i64 {
    (timestamp_ms + offset_ms).max(0)
}

use crate::contracts::{ActivitySignature, CorrelationConfig};

#[derive(Debug, Clone, PartialEq)]
pub struct CorrelationResult {
    pub offset_ms: i64,
    pub peak_score: f32,
    pub second_peak_score: f32,
    pub peak_margin: f32,
}

pub fn correlate(
    audio: &ActivitySignature,
    subtitle: &ActivitySignature,
    config: &CorrelationConfig,
) -> Result<CorrelationResult, String> {
    if audio.bucket_ms != subtitle.bucket_ms {
        return Err("bucket sizes must match".to_owned());
    }
    if config.max_offset_ms < config.min_offset_ms {
        return Err("maxOffsetMs must be >= minOffsetMs".to_owned());
    }
    if config.step_ms < audio.bucket_ms as i64 || config.step_ms % audio.bucket_ms as i64 != 0 {
        return Err("stepMs must be a multiple of bucketMs".to_owned());
    }

    let first_offset = ceil_to_step(config.min_offset_ms, config.step_ms);
    let last_offset = floor_to_step(config.max_offset_ms, config.step_ms);
    if first_offset > last_offset {
        return Ok(CorrelationResult {
            offset_ms: 0,
            peak_score: 0.0,
            second_peak_score: 0.0,
            peak_margin: 0.0,
        });
    }

    let mut best_offset = first_offset;
    let mut best_score = f32::NEG_INFINITY;
    let mut scored: Vec<(i64, f32)> = Vec::new();
    let mut offset = first_offset;
    while offset <= last_offset {
        let score = score_at_offset(audio, subtitle, offset, config);
        scored.push((offset, score));
        if score > best_score {
            best_score = score;
            best_offset = offset;
        }
        offset += config.step_ms;
    }

    let second = scored
        .iter()
        .filter(|(candidate, _)| (candidate - best_offset).abs() >= config.independent_peak_distance_ms)
        .map(|(_, score)| *score)
        .fold(0.0f32, f32::max);

    Ok(CorrelationResult {
        offset_ms: best_offset,
        peak_score: best_score.clamp(0.0, 1.0),
        second_peak_score: second.clamp(0.0, 1.0),
        peak_margin: (best_score - second).clamp(0.0, 1.0),
    })
}

fn score_at_offset(
    audio: &ActivitySignature,
    subtitle: &ActivitySignature,
    offset_ms: i64,
    config: &CorrelationConfig,
) -> f32 {
    let mut occupancy_raw = 0.0f32;
    let mut onset_raw = 0.0f32;
    let mut silence_raw = 0.0f32;
    let mut weighted_samples = 0.0f32;
    let bucket_ms = audio.bucket_ms as i64;

    for (i, a_value) in audio.occupancy.iter().enumerate() {
        let media_time_ms = audio.start_ms + i as i64 * bucket_ms;
        let source_subtitle_time_ms = media_time_ms - offset_ms;
        let relative = source_subtitle_time_ms - subtitle.start_ms;
        if relative < 0 {
            continue;
        }
        let subtitle_index = relative / subtitle.bucket_ms as i64;
        if subtitle_index < 0 || subtitle_index as usize >= subtitle.occupancy.len() {
            continue;
        }
        let idx = subtitle_index as usize;

        let a = a_value.clamp(0.0, 1.0);
        let s = subtitle.occupancy[idx].clamp(0.0, 1.0);
        let ao = audio.onsets[i].clamp(0.0, 1.0);
        let so = subtitle.onsets[idx].clamp(0.0, 1.0);

        occupancy_raw += a.min(s) - 0.90f32 * (a - s).abs();
        onset_raw += ao.min(so) - 0.65f32 * (ao - so).abs();
        silence_raw += (1.0f32 - a) * (1.0f32 - s);
        weighted_samples += 1.0f32;
    }

    if weighted_samples <= 0.0 {
        return 0.0;
    }
    let occupancy = normalize_signed(occupancy_raw / weighted_samples, -0.90, 1.0);
    let onset = normalize_signed(onset_raw / weighted_samples, -0.65, 1.0);
    let silence = (silence_raw / weighted_samples).clamp(0.0, 1.0);
    let total_weight = config.onset_weight.value()
        + config.occupancy_weight.value()
        + config.silence_weight.value();
    if total_weight <= 0.0 {
        return 0.0;
    }
    (config.onset_weight.value() * onset
        + config.occupancy_weight.value() * occupancy
        + config.silence_weight.value() * silence)
        / total_weight
}

fn normalize_signed(value: f32, min_value: f32, max_value: f32) -> f32 {
    ((value - min_value) / (max_value - min_value)).clamp(0.0, 1.0)
}

fn floor_to_step(value: i64, step: i64) -> i64 {
    value.div_euclid(step) * step
}

fn ceil_to_step(value: i64, step: i64) -> i64 {
    -(-value).div_euclid(step) * step
}

use serde_json::{json, Value};

use crate::contracts::{
    ActivitySignature, ParsedSubtitle, SubtitleCue, SyncMeasurement, SyncModel,
};

pub fn f32_value(value: f32) -> Value {
    json!({
        "decimal": value.to_string(),
        "bits": format!("{:08x}", value.to_bits()),
    })
}

pub fn f64_value(value: f64) -> Value {
    json!({
        "decimal": value.to_string(),
        "bits": format!("{:016x}", value.to_bits()),
    })
}

pub fn signature_value(signature: &ActivitySignature) -> Value {
    json!({
        "startMs": signature.start_ms,
        "bucketMs": signature.bucket_ms,
        "occupancy": signature.occupancy.iter().map(|v| f32_value(*v)).collect::<Vec<_>>(),
        "onsets": signature.onsets.iter().map(|v| f32_value(*v)).collect::<Vec<_>>(),
    })
}

pub fn cue_value(cue: &SubtitleCue) -> Value {
    json!({
        "index": cue.index,
        "startMs": cue.start_ms,
        "endMs": cue.end_ms,
        "rawText": cue.raw_text,
        "baseRtl": cue.base_rtl,
        "displayText": cue.display_text,
    })
}

pub fn subtitle_value(subtitle: &ParsedSubtitle) -> Value {
    json!({
        "language": subtitle.language,
        "sourceId": subtitle.source_id,
        "offsetMs": subtitle.offset_ms,
        "cues": subtitle.cues.iter().map(cue_value).collect::<Vec<_>>(),
    })
}

pub fn measurement_value(measurement: &SyncMeasurement) -> Value {
    json!({
        "subtitleProbeStartMs": measurement.subtitle_probe_start_ms,
        "audioProbeStartMs": measurement.audio_probe_start_ms,
        "estimatedOffsetMs": measurement.estimated_offset_ms,
        "correlationScore": f32_value(measurement.correlation_score.value()),
        "peakMargin": f32_value(measurement.peak_margin.value()),
        "speechCoverage": f32_value(measurement.speech_coverage.value()),
        "transitionCount": measurement.transition_count,
        "probeQuality": f32_value(measurement.probe_quality.value()),
    })
}

pub fn model_value(model: &SyncModel) -> Value {
    match model {
        SyncModel::Identity => json!({"kind": "Identity"}),
        SyncModel::Offset { offset_ms } => json!({"kind": "Offset", "offsetMs": offset_ms}),
        SyncModel::Affine { scale, offset_ms } => json!({
            "kind": "Affine",
            "scale": f64_value(scale.value()),
            "offsetMs": offset_ms,
        }),
        SyncModel::Piecewise { anchors } => json!({
            "kind": "Piecewise",
            "anchors": anchors.iter().map(|a| json!({
                "subtitleTimeMs": a.subtitle_time_ms,
                "mediaTimeMs": a.media_time_ms,
            })).collect::<Vec<_>>(),
        }),
    }
}

use serde_json::{json, Value};

use crate::contracts::{SyncMeasurement, SyncModel};
use crate::json_util::{f32_value, measurement_value, model_value};

const MINIMUM_GOOD_PROBES: usize = 2;
const MAXIMUM_CONSENSUS_SPREAD_MS: i64 = 300;
const IDENTITY_TOLERANCE_MS: i64 = 150;
const AUTO_APPLY_THRESHOLD: f32 = 0.86;
const MINIMUM_PROBE_QUALITY: f32 = 0.50;
const MINIMUM_CORRELATION_SCORE: f32 = 0.40;
const MINIMUM_PEAK_MARGIN: f32 = 0.035;

pub fn resolve(measurements: &[SyncMeasurement]) -> Value {
    let mut good: Vec<SyncMeasurement> = measurements
        .iter()
        .filter(|m| is_eligible(m))
        .cloned()
        .collect();
    good.sort_by_key(|m| m.subtitle_probe_start_ms);

    if good.len() < MINIMUM_GOOD_PROBES {
        return low_confidence(measurements);
    }

    let offset = weighted_median(&good);
    let spread = good
        .iter()
        .map(|m| m.estimated_offset_ms)
        .max()
        .unwrap()
        - good.iter().map(|m| m.estimated_offset_ms).min().unwrap();

    if spread <= MAXIMUM_CONSENSUS_SPREAD_MS {
        let unique_peaks = good
            .iter()
            .filter(|m| m.peak_margin.value() >= MINIMUM_PEAK_MARGIN)
            .count();
        if (good.len() == 2 && unique_peaks < 2) || (good.len() >= 3 && unique_peaks < 1) {
            return low_confidence(measurements);
        }

        let ratio = spread as f32 / MAXIMUM_CONSENSUS_SPREAD_MS.max(1) as f32;
        let agreement = (1.0f32 - ratio * ratio).clamp(0.0, 1.0);
        let evidence = average_f32(good.iter().map(|m| m.probe_quality.value())).clamp(0.0, 1.0);
        let uniqueness = average_f32(
            good.iter()
                .map(|m| (m.peak_margin.value() / 0.20f32).clamp(0.0, 1.0)),
        );
        let multi_probe_bonus = if good.len() >= 3 { 0.05f32 } else { 0.0 };
        let confidence = (0.68f32 * agreement
            + 0.22f32 * evidence
            + 0.10f32 * uniqueness
            + multi_probe_bonus)
            .clamp(0.0, 1.0);
        if confidence < AUTO_APPLY_THRESHOLD {
            return low_confidence(measurements);
        }

        let model = if offset.abs() <= IDENTITY_TOLERANCE_MS {
            SyncModel::Identity
        } else {
            SyncModel::Offset { offset_ms: offset }
        };
        return json!({
            "kind": "Synchronized",
            "model": model_value(&model),
            "confidence": f32_value(confidence),
            "measurements": measurements.iter().map(measurement_value).collect::<Vec<_>>(),
        });
    }

    if good.len() >= 3
        && good
            .iter()
            .any(|m| m.peak_margin.value() >= MINIMUM_PEAK_MARGIN)
        && is_likely_linear_drift(&good)
    {
        return json!({
            "kind": "ComplexDriftDetected",
            "measurements": measurements.iter().map(measurement_value).collect::<Vec<_>>(),
        });
    }

    low_confidence(measurements)
}

pub fn has_useful_provisional_offset(measurements: &[SyncMeasurement]) -> bool {
    measurements
        .last()
        .map(|m| is_eligible(m) && m.peak_margin.value() >= MINIMUM_PEAK_MARGIN * 0.5f32)
        .unwrap_or(false)
}

fn low_confidence(measurements: &[SyncMeasurement]) -> Value {
    json!({
        "kind": "LowConfidence",
        "measurements": measurements.iter().map(measurement_value).collect::<Vec<_>>(),
    })
}

fn is_eligible(m: &SyncMeasurement) -> bool {
    m.probe_quality.value() >= MINIMUM_PROBE_QUALITY
        && m.correlation_score.value() >= MINIMUM_CORRELATION_SCORE
}

fn weighted_median(measurements: &[SyncMeasurement]) -> i64 {
    let mut ordered = measurements.to_vec();
    ordered.sort_by_key(|m| m.estimated_offset_ms);
    let total_weight = (ordered
        .iter()
        .map(|m| m.probe_quality.value() as f64)
        .sum::<f64>())
    .max(1e-6);
    let mut running = 0.0f64;
    for measurement in &ordered {
        running += measurement.probe_quality.value() as f64;
        if running >= total_weight / 2.0 {
            return measurement.estimated_offset_ms;
        }
    }
    ordered.last().unwrap().estimated_offset_ms
}

fn average_f32(values: impl Iterator<Item = f32>) -> f32 {
    let values: Vec<f32> = values.collect();
    (values.iter().map(|v| *v as f64).sum::<f64>() / values.len() as f64) as f32
}

fn is_likely_linear_drift(measurements: &[SyncMeasurement]) -> bool {
    let xs: Vec<f64> = measurements
        .iter()
        .map(|m| m.subtitle_probe_start_ms as f64)
        .collect();
    let ys: Vec<f64> = measurements
        .iter()
        .map(|m| m.estimated_offset_ms as f64)
        .collect();
    let x_mean = xs.iter().sum::<f64>() / xs.len() as f64;
    let y_mean = ys.iter().sum::<f64>() / ys.len() as f64;
    let ss_x = xs.iter().map(|x| (x - x_mean) * (x - x_mean)).sum::<f64>();
    if ss_x <= 0.0 {
        return false;
    }
    let slope = xs
        .iter()
        .zip(ys.iter())
        .map(|(x, y)| (x - x_mean) * (y - y_mean))
        .sum::<f64>()
        / ss_x;
    let intercept = y_mean - slope * x_mean;
    let ss_tot = ys.iter().map(|y| (y - y_mean) * (y - y_mean)).sum::<f64>();
    if ss_tot <= 0.0 {
        return false;
    }
    let ss_res = xs
        .iter()
        .zip(ys.iter())
        .map(|(x, y)| {
