    let intercept = y_mean - slope * x_mean;
    let ss_tot = ys.iter().map(|y| (y - y_mean) * (y - y_mean)).sum::<f64>();
    if ss_tot <= 0.0 {
        return false;
    }
    let ss_res = xs
        .iter()
