91:             let base = buffer_offset + frame * frame_bytes;
92:             if base + frame_bytes > limit {
93:                 continue;
94:             }
95: 
96:             // The golden generator writes with Java ByteOrder.nativeOrder(); CI hosts are LE.
97:             let mut mono = 0.0f64;
98:             for channel in 0..channel_count as usize {
99:                 let index = base + channel * encoding.bytes_per_sample();
100:                 let sample = match encoding {
101:                     PcmSampleEncoding::Pcm16 => {
102:                         let raw = i16::from_ne_bytes(buffer[index..index + 2].try_into().unwrap());
103:                         raw as f64 / 32768.0
104:                     }
105:                     PcmSampleEncoding::PcmFloat => {
106:                         let raw = f32::from_ne_bytes(buffer[index..index + 4].try_into().unwrap());
107:                         (raw as f64).clamp(-1.0, 1.0)
108:                     }
109:                 };
110:                 mono += sample;
111:             }
112:             let mono = (mono / channel_count as f64).clamp(-1.0, 1.0);
113: 
114:             self.sum_squares[bucket] += mono * mono;
115:             if self.has_prior[bucket] {
116:                 let diff = mono - self.prior_sample[bucket];
117:                 self.diff_squares[bucket] += diff * diff;
118:                 if (mono >= 0.0) != (self.prior_sample[bucket] >= 0.0) {
119:                     self.zero_crossings[bucket] += 1;
120:                 }
121:             }
122:             self.prior_sample[bucket] = mono;
123:             self.has_prior[bucket] = true;
124:             self.sample_counts[bucket] += 1;
125:             self.decoded_sample_count += 1;
126:         }
127:     }
128: 
129:     pub fn finish(&self) -> ActivitySignature {
130:         let mut rms = vec![0.0f64; self.bucket_count];
131:         let mut diff_rms = vec![0.0f64; self.bucket_count];
132:         let mut zcr = vec![0.0f64; self.bucket_count];
133:         for i in 0..self.bucket_count {
134:             let n = self.sample_counts[i];
135:             if n <= 0 {
136:                 continue;
137:             }
138:             rms[i] = (self.sum_squares[i] / n as f64).sqrt();
139:             diff_rms[i] = (self.diff_squares[i] / n.max(1) as f64).sqrt();
140:             zcr[i] = self.zero_crossings[i] as f64 / n.max(1) as f64;
141:         }
142: 
143:         let mut valid_rms: Vec<f64> = (0..self.bucket_count)
144:             .filter(|i| self.sample_counts[*i] > 0)
145:             .map(|i| rms[i])
146:             .collect();
147:         valid_rms.sort_by(|a, b| a.total_cmp(b));
148:         let p20 = if valid_rms.is_empty() {
149:             0.0
150:         } else {
151:             valid_rms[((valid_rms.len() - 1) as f64 * 0.20) as usize]
152:         };
153:         let noise_floor = 0.003f64.max(p20);
154:         let mut raw = vec![0.0f32; self.bucket_count];
155: 
156:         for i in 0..self.bucket_count {
157:             if self.sample_counts[i] == 0 {
158:                 continue;
159:             }
160:             let energy_ratio = (rms[i] + 1e-9) / (noise_floor * 1.25 + 1e-9);
161:             let energy = (energy_ratio.ln() / 5.0f64.ln()).clamp(0.0, 1.0);
162:             if energy < 0.08 {
163:                 continue;
164:             }
165:             let zcr_score = trapezoid_score(zcr[i], 0.008, 0.025, 0.22, 0.38);
166:             let derivative_ratio = diff_rms[i] / (rms[i] + 1e-9);
167:             let derivative_score = trapezoid_score(derivative_ratio, 0.03, 0.10, 1.10, 1.90);
168:             raw[i] = (energy * (0.65 + 0.20 * zcr_score + 0.15 * derivative_score)) as f32;
169:             raw[i] = raw[i].clamp(0.0, 1.0);
170:         }
171: 
172:         let occupancy = smooth(&raw);
173:         let mut onsets = vec![0.0f32; self.bucket_count];
174:         for i in 0..self.bucket_count {
175:             let previous = if i == 0 { 0.0f32 } else { occupancy[i - 1] };
176:             let rise = (occupancy[i] - previous).max(0.0);
177:             if rise < 0.12f32 {
178:                 continue;
179:             }
180:             for d in -3..=3 {
181:                 let target = i as i32 + d;
182:                 if target < 0 || target >= self.bucket_count as i32 {
183:                     continue;
184:                 }
185:                 let kernel = match d.abs() {
186:                     0 => 1.0f32,
187:                     1 => 0.65f32,
188:                     2 => 0.35f32,
189:                     _ => 0.15f32,
190:                 };
191:                 onsets[target as usize] = onsets[target as usize].max(rise * kernel);
192:             }
193:         }
194: 
195:         ActivitySignature {
196:             start_ms: self.target_start_us / 1_000,
197:             bucket_ms: self.bucket_ms,
198:             occupancy,
199:             onsets,
200:         }
201:     }
202: }
203: 
204: fn smooth(input: &[f32]) -> Vec<f32> {
205:     if input.len() < 3 {
206:         return input.to_vec();
207:     }
208:     let mut out = vec![0.0f32; input.len()];
209:     for i in 0..input.len() {
210:         let mut weighted = input[i] * 0.50f32;
211:         let mut total = 0.50f32;
212:         if i > 0 {
213:             weighted += input[i - 1] * 0.25f32;
214:             total += 0.25f32;
215:         }
216:         if i + 1 < input.len() {
217:             weighted += input[i + 1] * 0.25f32;
218:             total += 0.25f32;
219:         }
220:         out[i] = (weighted / total).clamp(0.0, 1.0);
221:     }
222:     for i in 1..out.len() - 1 {
223:         if out[i] > 0.45 && out[i - 1] < 0.10 && out[i + 1] < 0.10 {
224:             out[i] *= 0.35;
225:         }
226:     }
227:     out
228: }
229: 
230: fn trapezoid_score(value: f64, low0: f64, low1: f64, high1: f64, high0: f64) -> f64 {
231:     let score = if value <= low0 || value >= high0 {
232:         0.0
233:     } else if value < low1 {
234:         (value - low0) / (low1 - low0)
235:     } else if value <= high1 {
236:         1.0
237:     } else {
238:         (high0 - value) / (high0 - high1)
239:     };
240:     score.clamp(0.0, 1.0)
241: }
242: 
243: /// Reproduce the deterministic golden PCM signal without committing copyrighted media.
244: pub fn synthesize_golden_pcm(sample_rate: i32, sample_count: i64, encoding: PcmSampleEncoding) -> Vec<u8> {
245:     let mut bytes = Vec::with_capacity((sample_count as usize) * encoding.bytes_per_sample());
246:     for sample in 0..sample_count {
247:         let time_ms = sample * 1_000 / sample_rate as i64;
248:         let in_burst = (1_000..=2_000).contains(&time_ms)
249:             || (3_000..=4_000).contains(&time_ms)
250:             || (5_000..=6_000).contains(&time_ms);
251:         let value = if in_burst {
252:             0.3f64 * (2.0f64 * std::f64::consts::PI * 200.0 * sample as f64 / sample_rate as f64).sin()
253:         } else {
254:             0.0
255:         };
256:         match encoding {
257:             PcmSampleEncoding::Pcm16 => {
258:                 let raw = (value * 32_767.0) as i16;
259:                 bytes.extend_from_slice(&raw.to_ne_bytes());
260:             }
261:             PcmSampleEncoding::PcmFloat => {
262:                 bytes.extend_from_slice(&(value as f32).to_ne_bytes());
263:             }
264:         }
265:     }
266:     bytes
267: }

