134: fn main() -> ExitCode {
135:     let golden_dir = env::args()
136:         .nth(1)
137:         .map(PathBuf::from)
138:         .unwrap_or_else(|| PathBuf::from("testdata/golden"));
139:     let mut files: Vec<PathBuf> = match fs::read_dir(&golden_dir) {
140:         Ok(entries) => entries
141:             .filter_map(Result::ok)
142:             .map(|entry| entry.path())
143:             .filter(|path| path.extension().and_then(|s| s.to_str()) == Some("json"))
144:             .collect(),
145:         Err(error) => {
146:             eprintln!("cannot read {}: {error}", golden_dir.display());
147:             return ExitCode::FAILURE;
148:         }
149:     };
150:     files.sort();
151: 
152:     let mut total_cases = 0usize;
153:     let mut failures: Vec<String> = Vec::new();
154: 
155:     for path in files {
156:         let text = match fs::read_to_string(&path) {
157:             Ok(text) => text,
158:             Err(error) => {
159:                 failures.push(format!("{}: {error}", path.display()));
160:                 continue;
161:             }
162:         };
163:         let golden: GoldenFile = match serde_json::from_str(&text) {
164:             Ok(golden) => golden,
165:             Err(error) => {
166:                 failures.push(format!("{}: invalid golden JSON: {error}", path.display()));
167:                 continue;
168:             }
169:         };
170:         println!("[{}] {} cases", golden.component, golden.cases.len());
171:         for case in &golden.cases {
172:             total_cases += 1;
173:             let path_label = format!("{}/{}", golden.component, case.id);
174:             match run_case(&golden.component, case) {
175:                 Ok(actual) => {
176:                     let mut errors = Vec::new();
177:                     compare(&case.output, &actual, "$", &mut errors);
178:                     if errors.is_empty() {
179:                         println!("  PASS {path_label}");
180:                     } else {
181:                         println!("  FAIL {path_label}");
182:                         for error in errors {
183:                             failures.push(format!("{path_label}: {error}"));
184:                         }
185:                     }
186:                 }
187:                 Err(error) => {
188:                     println!("  FAIL {path_label}");
189:                     failures.push(format!("{path_label}: {error}"));
190:                 }
191:             }
192:         }
193:     }
194: 
195:     println!("\nRust parity: {total_cases} cases, {} failures", failures.len());
196:     for failure in &failures {
197:         println!("  {failure}");
198:     }
199:     if failures.is_empty() {
200:         ExitCode::SUCCESS
201:     } else {
202:         ExitCode::FAILURE
203:     }
