317: /// D-3: 1e-6 tolerance for derived floats; bit-exact integers, Longs, hashes and strings.
318: /// Raw bits are diagnostic only: bit equality is an accepted fast path, never a requirement.
319: fn compare(expected: &Value, actual: &Value, path: &str, errors: &mut Vec<String>) {
320:     match (expected, actual) {
321:         (Value::Object(e), Value::Object(a))
322:             if e.contains_key("decimal") && e.contains_key("bits") =>
323:         {
324:             let expected_bits = e["bits"].as_str().unwrap_or("");
325:             let actual_bits = a["bits"].as_str().unwrap_or("");
326:             if expected_bits == actual_bits {
327:                 return;
328:             }
329:             let expected_value = parse_float(e);
330:             let actual_value = parse_float(a);
331:             match (expected_value, actual_value) {
332:                 (Some(e_value), Some(a_value)) if (e_value - a_value).abs() <= FLOAT_TOLERANCE => {}
333:                 _ => errors.push(format!(
334:                     "{path}: float mismatch expected(decimal={}, bits={}) actual(decimal={}, bits={})",
335:                     e["decimal"].as_str().unwrap_or("?"),
336:                     expected_bits,
337:                     a["decimal"].as_str().unwrap_or("?"),
338:                     actual_bits,
339:                 )),
340:             }
341:         }
342:         (Value::Object(e), Value::Object(a)) => {
343:             let mut keys: Vec<&String> = e.keys().chain(a.keys()).collect();
344:             keys.sort();
345:             keys.dedup();
346:             for key in keys {
347:                 let child_path = format!("{path}.{key}");
348:                 match (e.get(key), a.get(key)) {
349:                     (Some(e_value), Some(a_value)) => compare(e_value, a_value, &child_path, errors),
350:                     _ => errors.push(format!("{child_path}: missing key")),
351:                 }
352:             }
353:         }
354:         (Value::Array(e), Value::Array(a)) => {
355:             if e.len() != a.len() {
356:                 errors.push(format!("{path}: array length expected {} actual {}", e.len(), a.len()));
357:                 return;
358:             }
359:             for (index, (e_value, a_value)) in e.iter().zip(a.iter()).enumerate() {
360:                 compare(e_value, a_value, &format!("{path}[{index}]"), errors);
361:             }
362:         }
363:         (Value::Number(_), Value::Number(_)) => {
364:             if expected != actual {
365:                 errors.push(format!("{path}: expected {expected} actual {actual}"));
366:             }
367:         }
368:         (Value::String(e), Value::String(a)) => {
369:             if e != a {
370:                 errors.push(format!("{path}: expected {e:?} actual {a:?}"));
371:             }
372:         }
373:         (Value::Bool(e), Value::Bool(a)) => {
374:             if e != a {
375:                 errors.push(format!("{path}: expected {e} actual {a}"));
376:             }
377:         }
378:         (Value::Null, Value::Null) => {}
379:         _ => errors.push(format!("{path}: shape mismatch expected {expected} actual {actual}")),
380:     }
381: }
382: 
383: fn parse_float(value: &serde_json::Map<String, Value>) -> Option<f32> {
384:     if let Some(decimal) = value.get("decimal").and_then(Value::as_str) {
385:         if let Ok(parsed) = decimal.parse::<f32>() {
386:             return Some(parsed);
387:         }
388:     }
389:     let bits = u32::from_str_radix(value.get("bits").and_then(Value::as_str).unwrap_or(""), 16).ok()?;
390:     Some(f32::from_bits(bits))
391: }

