4: /// The golden corpus stores deterministic synthetic patterns rather than copyrighted media.
5: pub fn hash_synthetic(size: usize, pattern: &str) -> Result<String, String> {
6:     if size < MIN_FILE_SIZE {
7:         return Err(format!(
8:             "File must be at least {MIN_FILE_SIZE} bytes for OpenSubtitles hashing"
9:         ));
10:     }
11:     let mut bytes = vec![0u8; size];
12:     match pattern {
13:         "zeros_128k" | "zeros_256k" => {}
14:         "head_and_tail_words" => {
15:             bytes[0] = 1;
16:             bytes[CHUNK_SIZE] = 2;
17:         }
18:         "high_bit_head" => bytes[7] = 0x80,
19:         other => return Err(format!("unknown golden hash pattern: {other}")),
20:     }
21:     Ok(hash_bytes(&bytes))
22: }
23: 
24: pub fn hash_bytes(bytes: &[u8]) -> String {
25:     let file_size = bytes.len() as u64;
26:     let head = sum_chunk(bytes, 0);
27:     let tail = sum_chunk(bytes, bytes.len() - CHUNK_SIZE);
28:     let hash = file_size.wrapping_add(head).wrapping_add(tail);
29:     format!("{hash:016x}")
30: }
31: 
32: fn sum_chunk(bytes: &[u8], offset: usize) -> u64 {
33:     let mut sum = 0u64;
34:     for i in 0..(CHUNK_SIZE / 8) {
35:         let start = offset + i * 8;
36:         let word = u64::from_le_bytes(bytes[start..start + 8].try_into().unwrap());
37:         sum = sum.wrapping_add(word);
38:     }
39:     sum
40: }

