87:         val yMean = ys.average()
88:         val ssX = xs.sumOf { (it - xMean) * (it - xMean) }
89:         if (ssX <= 0.0) return false
90:         val slope = xs.indices.sumOf { i -> (xs[i] - xMean) * (ys[i] - yMean) } / ssX
