15: fn map_piecewise(time_ms: i64, anchors: &[crate::contracts::SyncAnchor]) -> i64 {
16:     let mut anchors = anchors.to_vec();
17:     anchors.sort_by_key(|anchor| anchor.subtitle_time_ms);
18:     if anchors.is_empty() {
19:         return time_ms;
20:     }
21:     if anchors.len() == 1 {
22:         return time_ms + (anchors[0].media_time_ms - anchors[0].subtitle_time_ms);
23:     }
24:     if time_ms <= anchors[0].subtitle_time_ms {
25:         let a = &anchors[0];
26:         return time_ms + (a.media_time_ms - a.subtitle_time_ms);
27:     }
28:     if time_ms >= anchors[anchors.len() - 1].subtitle_time_ms {
29:         let a = &anchors[anchors.len() - 1];
30:         return time_ms + (a.media_time_ms - a.subtitle_time_ms);
31:     }
32:     let right_index = anchors
33:         .iter()
34:         .position(|anchor| anchor.subtitle_time_ms >= time_ms)
35:         .unwrap();
36:     let left = &anchors[right_index - 1];
37:     let right = &anchors[right_index];
38:     let span = (right.subtitle_time_ms - left.subtitle_time_ms).max(1);
39:     let t = (time_ms - left.subtitle_time_ms) as f64 / span as f64;
40:     kotlin_round_to_long(
41:         left.media_time_ms as f64 + t * (right.media_time_ms - left.media_time_ms) as f64,
42:     )
